window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6553ff6651ac06d7"]={"versions": [{"id": "FIG-6553ff6651ac06d7", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>cd Data Model</code>) aus der Spezifikation des AUTOSAR CAN Transport Layer (<code>AUTOSAR_SWS_CAN_TP</code>). Das Diagramm modelliert die strukturellen Beziehungen und Zuordnungen zwischen Daten- und Adressierungsentitäten der Netzwerk-Schicht (Network Layer, N-SDU / N_AI) und der Sicherungsschicht (Data Link Layer, L-SDU / LSduId) im AUTOSAR BSW Communication Stack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Datenmodell definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>N-SDU</code>: Repräsentiert die Service Data Unit der Netzwerkschicht; über eine 1:1-Assoziation fest verknüpft mit <code>NSduId</code>.\n</li><li><code>NSduId</code>: Eindeutiger Bezeichner der N-SDU; 1:1 assoziiert mit <code>N_AI</code>.\n</li><li><code>N_AI</code>: Network Address Information; besitzt eine Komposition zu <code>LSduId</code> mit Multiplizität <code>1</code> zu <code>1..*</code> sowie eine Komposition zu <code>N_TA</code> (Network Target Address) mit Multiplizität <code>1</code> zu <code>0..1</code>.\n</li><li><code>N_TA</code>: Optionale Zieladresse im Adressierungskontext.\n</li><li><code>LSduId</code>: Bezeichner der Data Link Layer SDU; steht in einer 1:1-Assoziation zu <code>L-SDU</code>.\n</li><li><code>L-SDU</code>: Abstrakte Basisklasse bzw. generische PDU der Sicherungsschicht, von der über Generalisierungs-/Vererbungspfeile die vier CAN-TP-PCI-Frametypen abgeleitet sind:\n<ul class=\"fig-list\"><li><code>FC</code>: Flow Control Frame\n</li><li><code>SF</code>: Single Frame\n</li><li><code>FF</code>: First Frame\n</li><li><code>CF</code>: Consecutive Frame\n</li></ul>\n</li><li>Eine textuelle Constraint-Notiz spezifiziert:\n<ul class=\"fig-list\"><li>SF, FF und CF nutzen dieselbe <code>LSduId</code>.\n</li><li>FC nutzt eine abweichende <code>LSduId</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Interaktionssequenz. Die Beziehungen steuern zur Laufzeit das Mapping: Eintreffende bzw. zu versendende N-PDUs werden anhand der <code>NSduId</code> über <code>N_AI</code> aufgelöst. Bei segmentierter oder unsegmentierter Übertragung nutzen Nutzdaten-Frames (SF, FF, CF) dieselbe zugewiesene <code>LSduId</code>, während für die Flusssteuerung (FC) in Gegenrichtung eine separate <code>LSduId</code> herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Modellierung der Identifier- und Adressbeziehungen für die CAN-TP-Konfiguration. Entwickler und Konfiguratoren müssen sicherstellen, dass pro <code>N_AI</code> mindestens eine und bei bidirektionaler Flusssteuerung mehrere <code>LSduId</code>s hinterlegt sind. Die Constraint-Bedingung erfordert im AUTOSAR-Datenmodell/ECUC-Mapping zwingend getrennte PDU-Identifier für Daten-Frames (SF, FF, CF) und Flow-Control-Frames (FC).</p>"}, {"id": "FIG-36bc306bd0dd6816", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>cd Data Model</code>) aus der Spezifikation des AUTOSAR CAN Transport Layer (<code>AUTOSAR_SWS_CAN_TP</code>). Das Diagramm modelliert die strukturellen Beziehungen und Zuordnungen zwischen Daten- und Adressierungsentitäten der Netzwerk-Schicht (Network Layer, N-SDU / N_AI) und der Sicherungsschicht (Data Link Layer, L-SDU / LSduId) im AUTOSAR BSW Communication Stack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Datenmodell definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>N-SDU</code>: Repräsentiert die Service Data Unit der Netzwerkschicht; über eine 1:1-Assoziation fest verknüpft mit <code>NSduId</code>.\n</li><li><code>NSduId</code>: Eindeutiger Bezeichner der N-SDU; 1:1 assoziiert mit <code>N_AI</code>.\n</li><li><code>N_AI</code>: Network Address Information; besitzt eine Komposition zu <code>LSduId</code> mit Multiplizität <code>1</code> zu <code>1..*</code> sowie eine Komposition zu <code>N_TA</code> (Network Target Address) mit Multiplizität <code>1</code> zu <code>0..1</code>.\n</li><li><code>N_TA</code>: Optionale Zieladresse im Adressierungskontext.\n</li><li><code>LSduId</code>: Bezeichner der Data Link Layer SDU; steht in einer 1:1-Assoziation zu <code>L-SDU</code>.\n</li><li><code>L-SDU</code>: Abstrakte Basisklasse bzw. generische PDU der Sicherungsschicht, von der über Generalisierungs-/Vererbungspfeile die vier CAN-TP-PCI-Frametypen abgeleitet sind:\n<ul class=\"fig-list\"><li><code>FC</code>: Flow Control Frame\n</li><li><code>SF</code>: Single Frame\n</li><li><code>FF</code>: First Frame\n</li><li><code>CF</code>: Consecutive Frame\n</li></ul>\n</li><li>Eine textuelle Constraint-Notiz spezifiziert:\n<ul class=\"fig-list\"><li>SF, FF und CF nutzen dieselbe <code>LSduId</code>.\n</li><li>FC nutzt eine abweichende <code>LSduId</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Interaktionssequenz. Die Beziehungen steuern zur Laufzeit das Mapping: Eintreffende bzw. zu versendende N-PDUs werden anhand der <code>NSduId</code> über <code>N_AI</code> aufgelöst. Bei segmentierter oder unsegmentierter Übertragung nutzen Nutzdaten-Frames (SF, FF, CF) dieselbe zugewiesene <code>LSduId</code>, während für die Flusssteuerung (FC) in Gegenrichtung eine separate <code>LSduId</code> herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Modellierung der Identifier- und Adressbeziehungen für die CAN-TP-Konfiguration. Entwickler und Konfiguratoren müssen sicherstellen, dass pro <code>N_AI</code> mindestens eine und bei bidirektionaler Flusssteuerung mehrere <code>LSduId</code>s hinterlegt sind. Die Constraint-Bedingung erfordert im AUTOSAR-Datenmodell/ECUC-Mapping zwingend getrennte PDU-Identifier für Daten-Frames (SF, FF, CF) und Flow-Control-Frames (FC).</p>"}], "trans": [{"from": "FIG-6553ff6651ac06d7", "to": "FIG-36bc306bd0dd6816", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
